import type { Dictionary, GameData } from './game-data.ts';

// Generated by scripts/build-data.ts. Each file becomes its own lazily loaded,
// content-hashed chunk, which the service worker precaches for offline use.
const gameFiles = import.meta.glob<GameData>('../generated/games/*/data.json', { import: 'default' });
const dictionaryFiles = import.meta.glob<Dictionary>('../generated/games/*/i18n/*.json', { import: 'default' });

export async function loadGame(gameId: string): Promise<GameData> {
  const load = gameFiles[`../generated/games/${gameId}/data.json`];
  if (!load) throw new Error(`Unknown game "${gameId}"`);
  return load();
}

export async function loadDictionary(gameId: string, locale: string, fallback = 'en'): Promise<Dictionary> {
  const load =
    dictionaryFiles[`../generated/games/${gameId}/i18n/${locale}.json`] ??
    dictionaryFiles[`../generated/games/${gameId}/i18n/${fallback}.json`];
  if (!load) throw new Error(`No names for game "${gameId}"`);
  return load();
}
